// ============================================================================
// startup-filings — real regulatory filings for private companies.
//
// Nothing here is generated by a model. Every row comes from a government or
// regulator system and carries the source and a link to the original document.
//
//   SEC EDGAR (US)      free  registrant filing history + Form D offering data
//   GLEIF (global)      free  legal entity record, jurisdiction, status
//   VIES (EU)           free  official VAT registration check
//   CORDIS (EU)         free  EU-funded project participations
//   Registro Imprese IT free  innovative-startup special section (deep link)
// ============================================================================

import { lookupRegistries, type RegistryRecord } from './company-registries.ts';

export interface StartupFiling {
  source: string;            // "SEC EDGAR", "Registro Imprese", ...
  jurisdiction: string;      // ISO country code
  form: string;              // "D", "10-K", "Iscrizione sezione speciale", ...
  title: string;
  date: string | null;
  url: string;
  summary?: string | null;
  amount?: number | null;
  currency?: string | null;
  verified: boolean;         // true = fetched from the register, false = pointer
}

export interface StartupFilingsResult {
  company: string;
  country?: string | null;
  filings: StartupFiling[];
  entities: RegistryRecord[];
  sourcesQueried: string[];
  warnings: string[];
  asOf: string;
}

const UA = { 'User-Agent': 'VelaResearch/1.0 (filings lookup; contact@vela.ai)' };

async function jget(url: string, headers: Record<string, string> = {}, ms = 12000): Promise<any | null> {
  try {
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), ms);
    const r = await fetch(url, { headers: { ...UA, Accept: 'application/json', ...headers }, signal: ctl.signal });
    clearTimeout(t);
    if (!r.ok) return null;
    return await r.json();
  } catch { return null; }
}

async function tget(url: string, ms = 12000): Promise<string | null> {
  try {
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), ms);
    const r = await fetch(url, { headers: UA, signal: ctl.signal });
    clearTimeout(t);
    if (!r.ok) return null;
    return await r.text();
  } catch { return null; }
}

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const similar = (a: string, b: string) => {
  const x = norm(a), y = norm(b);
  return !!x && !!y && (x === y || x.startsWith(y) || y.startsWith(x) || x.includes(y));
};

// ------------------------------------------------------------------ SEC EDGAR

const FORM_LABEL: Record<string, string> = {
  D: 'Form D — exempt offering of securities',
  'D/A': 'Form D/A — amended exempt offering',
  'S-1': 'Form S-1 — registration statement',
  'S-1/A': 'Form S-1/A — amended registration statement',
  'C': 'Form C — crowdfunding offering',
  '1-A': 'Form 1-A — Regulation A offering',
  '8-K': 'Form 8-K — material event',
  '10-K': 'Form 10-K — annual report',
  '10-Q': 'Form 10-Q — quarterly report',
};

/** Resolve CIK numbers for a company name through EDGAR full-text search. */
async function secCiks(name: string): Promise<Array<{ cik: string; display: string }>> {
  const out = new Map<string, string>();

  const efts = await jget(`https://efts.sec.gov/LATEST/search-index?q=${encodeURIComponent(`"${name}"`)}`);
  for (const h of efts?.hits?.hits ?? []) {
    const src = h?._source ?? {};
    const display = (src.display_names ?? [])[0] ?? '';
    const cik = String(src.ciks?.[0] ?? '');
    if (!cik || !similar(display.replace(/\s*\(CIK.*/i, ''), name)) continue;
    out.set(cik.padStart(10, '0'), display);
  }

  if (out.size === 0) {
    const atom = await tget(
      `https://www.sec.gov/cgi-bin/browse-edgar?company=${encodeURIComponent(name)}&type=&dateb=&owner=include&count=10&action=getcompany&output=atom`,
    );
    for (const b of (atom ?? '').split('<entry>').slice(1, 6)) {
      const legal = b.match(/<conformed-name>([^<]+)</i)?.[1] ?? '';
      const cik = b.match(/<cik>(\d+)</i)?.[1];
      if (cik && similar(legal, name)) out.set(cik.padStart(10, '0'), legal.trim());
    }
  }

  return [...out].slice(0, 3).map(([cik, display]) => ({ cik, display }));
}

/** Parse the offering amounts out of a Form D primary document. */
function parseFormD(xml: string): { total?: number | null; sold?: number | null; industry?: string | null } {
  const num = (tag: string) => {
    const v = xml.match(new RegExp(`<${tag}>([^<]+)<`, 'i'))?.[1];
    const n = Number(String(v ?? '').replace(/[^0-9.]/g, ''));
    return Number.isFinite(n) && n > 0 ? n : null;
  };
  return {
    total: num('totalOfferingAmount'),
    sold: num('totalAmountSold'),
    industry: xml.match(/<industryGroupType>([^<]+)</i)?.[1] ?? null,
  };
}

async function sec(name: string): Promise<{ filings: StartupFiling[]; entities: RegistryRecord[]; warnings: string[] }> {
  const filings: StartupFiling[] = [];
  const entities: RegistryRecord[] = [];
  const warnings: string[] = [];

  const ciks = await secCiks(name);
  if (ciks.length === 0) return { filings, entities, warnings };

  for (const { cik, display } of ciks) {
    const sub = await jget(`https://data.sec.gov/submissions/CIK${cik}.json`);
    if (!sub) { warnings.push('SEC EDGAR did not answer for one registrant; try again in a moment.'); continue; }

    const bare = String(Number(cik));
    entities.push({
      register: 'SEC EDGAR',
      jurisdiction: 'US',
      legalName: sub.name ?? display,
      identifier: bare,
      identifierType: 'CIK',
      status: sub.entityType ?? 'Registrant',
      registeredAt: null,
      address: [sub.addresses?.business?.city, sub.addresses?.business?.stateOrCountry].filter(Boolean).join(', ') || null,
      activity: sub.sicDescription ?? null,
      url: `https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=${bare}&type=&dateb=&owner=include&count=40`,
    });

    const r = sub.filings?.recent ?? {};
    const n = Math.min(r.form?.length ?? 0, 60);
    const formDDocs: Array<{ i: number; url: string }> = [];

    for (let i = 0; i < n; i++) {
      const form = String(r.form[i] ?? '');
      const adsh = String(r.accessionNumber[i] ?? '').replace(/-/g, '');
      const doc = String(r.primaryDocument[i] ?? '');
      const url = adsh
        ? `https://www.sec.gov/Archives/edgar/data/${bare}/${adsh}/${doc || ''}`
        : `https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=${bare}`;
      const filing: StartupFiling = {
        source: 'SEC EDGAR',
        jurisdiction: 'US',
        form,
        title: FORM_LABEL[form] ?? `Form ${form}`,
        date: r.filingDate?.[i] ?? null,
        url,
        summary: r.primaryDocDescription?.[i] || sub.name || display,
        verified: true,
      };
      if (form.startsWith('D') && formDDocs.length < 3 && doc.endsWith('.xml')) formDDocs.push({ i: filings.length, url });
      filings.push(filing);
    }

    // Offering size lives inside the Form D document itself.
    // The rendered viewer path (xslFormDX01) hides the raw XML values.
    const docs = await Promise.allSettled(formDDocs.map((d) => tget(d.url.replace(/xslFormDX01\//, ''))));
    docs.forEach((res, k) => {
      if (res.status !== 'fulfilled' || !res.value) return;
      const parsed = parseFormD(res.value);
      const target = filings[formDDocs[k].i];
      if (!target) return;
      target.amount = parsed.sold ?? parsed.total ?? null;
      target.currency = target.amount ? 'USD' : null;
      const parts = [
        parsed.total ? `offering ${parsed.total.toLocaleString('en-US')} USD` : null,
        parsed.sold ? `sold ${parsed.sold.toLocaleString('en-US')} USD` : null,
        parsed.industry,
      ].filter(Boolean);
      if (parts.length) target.summary = parts.join(' · ');
    });
  }

  return { filings, entities, warnings };
}

// -------------------------------------------------------------------- Italy

/**
 * The innovative-startup special section of the Registro Imprese is published
 * by InfoCamere behind a browser challenge, so it cannot be queried
 * server-to-server. We return the official entry points as unverified pointers
 * and mark them clearly, rather than inventing a status.
 */
function italyPointers(name: string): StartupFiling[] {
  const q = encodeURIComponent(name);
  return [
    {
      source: 'Registro Imprese — sezione speciale startup innovative',
      jurisdiction: 'IT',
      form: 'Iscrizione sezione speciale',
      title: 'Check the innovative-startup registration for this company',
      date: null,
      url: `https://startup.registroimprese.it/isin/search?0&__checkbox_flagStartup=true&denominazione=${q}`,
      summary: 'Official register of innovative startups (D.L. 179/2012). Open the register to confirm the registration date and current requirements.',
      verified: false,
    },
    {
      source: 'Registro Imprese — report ufficiale',
      jurisdiction: 'IT',
      form: 'Elenco ufficiale',
      title: 'Full official list of Italian innovative startups (PDF)',
      date: null,
      url: 'https://startup.registroimprese.it/isin/report?reportType=startup',
      summary: 'Updated list published by InfoCamere for the Ministry of Enterprise.',
      verified: false,
    },
    {
      source: 'MIMIT / InfoCamere',
      jurisdiction: 'IT',
      form: 'Rapporto trimestrale',
      title: 'Quarterly report on innovative startups',
      date: null,
      url: 'https://startup.registroimprese.it/isin/static/startup/index.html?slideJump=25',
      summary: 'Ministry quarterly statistics on the special section.',
      verified: false,
    },
  ];
}

/** Official EU VAT registration check — confirms the legal name and address. */
async function vies(country: string, vat: string): Promise<StartupFiling | null> {
  const clean = vat.replace(/[^0-9A-Za-z]/g, '');
  if (clean.length < 8) return null;
  const j = await jget(`https://ec.europa.eu/taxation_customs/vies/rest-api/ms/${country}/vat/${clean}`);
  if (!j || j.isValid !== true) return null;
  return {
    source: 'VIES (European Commission)',
    jurisdiction: country,
    form: 'VAT registration',
    title: `${j.name ?? 'Registered'} — VAT ${country}${clean} active`,
    date: (j.requestDate ?? '').slice(0, 10) || null,
    url: 'https://ec.europa.eu/taxation_customs/vies/',
    summary: j.address ? String(j.address).replace(/\n/g, ', ') : null,
    verified: true,
  };
}

/** EU-funded research and innovation projects the company took part in. */
async function cordis(name: string): Promise<StartupFiling[]> {
  const q = encodeURIComponent(`contenttype='project' AND '${name}'`);
  const j = await jget(
    `https://cordis.europa.eu/api/search/results?q=${q}&format=json&p=1&num=10&srt=/project/contentUpdateDate:decreasing`,
    {}, 15000,
  );
  const rows: any[] = j?.payload?.results ?? [];
  return rows.slice(0, 8).map((r) => {
    const id = r.id ?? r.rcn ?? '';
    return {
      source: 'CORDIS (European Commission)',
      jurisdiction: 'EU',
      form: 'EU-funded project',
      title: r.title ?? `Project ${id}`,
      date: (r.startDate ?? r.contentUpdateDate ?? '').slice(0, 10) || null,
      url: id ? `https://cordis.europa.eu/project/id/${id}` : 'https://cordis.europa.eu/projects',
      summary: r.programme ?? r.frameworkProgramme ?? null,
      amount: Number(r.ecMaxContribution) || null,
      currency: Number(r.ecMaxContribution) ? 'EUR' : null,
      verified: true,
    } as StartupFiling;
  });
}

// --------------------------------------------------------------- entrypoint

export async function fetchStartupFilings(input: {
  name: string;
  country?: string;
}): Promise<StartupFilingsResult> {
  const name = (input.name || '').trim();
  const cc = (input.country || '').toUpperCase();
  const asOf = new Date().toISOString();

  if (name.length < 2) {
    return { company: name, country: cc || null, filings: [], entities: [], sourcesQueried: [], warnings: ['A company name of at least 2 characters is required.'], asOf };
  }

  const sourcesQueried: string[] = ['GLEIF'];
  const warnings: string[] = [];
  const filings: StartupFiling[] = [];
  const entities: RegistryRecord[] = [];

  const wantsUS = !cc || cc === 'US';
  const wantsEU = !cc || !['US', 'GB', 'CH', 'CA', 'AU', 'JP'].includes(cc);
  const wantsIT = cc === 'IT' || !cc;

  const tasks: Array<Promise<any>> = [lookupRegistries(name, cc || undefined)];
  if (wantsUS) { tasks.push(sec(name)); sourcesQueried.push('SEC EDGAR (US)'); }
  if (wantsEU) { tasks.push(cordis(name)); sourcesQueried.push('CORDIS (EU)'); }

  const settled = await Promise.allSettled(tasks);

  const reg = settled[0];
  if (reg.status === 'fulfilled' && reg.value) {
    entities.push(...(reg.value.records ?? []));
    warnings.push(...(reg.value.warnings ?? []));
    for (const f of reg.value.filings ?? []) {
      filings.push({
        source: f.register,
        jurisdiction: entities[0]?.jurisdiction ?? cc ?? '',
        form: f.type,
        title: f.title,
        date: f.date,
        url: f.url,
        summary: null,
        verified: true,
      });
    }
    // A register entry is itself a filing event worth showing.
    for (const r of reg.value.records ?? []) {
      if (!r.identifier || !r.registeredAt) continue;
      filings.push({
        source: r.register,
        jurisdiction: r.jurisdiction || cc,
        form: 'Registration',
        title: `${r.legalName} registered (${r.identifierType} ${r.identifier})`,
        date: r.registeredAt,
        url: r.url ?? '',
        summary: [r.status, r.address].filter(Boolean).join(' · ') || null,
        verified: true,
      });
    }
  }

  for (const s of settled.slice(1)) {
    if (s.status !== 'fulfilled' || !s.value) continue;
    if (Array.isArray(s.value)) filings.push(...s.value);
    else {
      filings.push(...(s.value.filings ?? []));
      entities.push(...(s.value.entities ?? []));
      warnings.push(...(s.value.warnings ?? []));
    }
  }

  // Italy: official VAT check where a register gave us a numeric identifier,
  // plus the official innovative-startup entry points.
  if (wantsIT && (cc === 'IT' || entities.some((e) => e.jurisdiction === 'IT'))) {
    sourcesQueried.push('Registro Imprese — startup innovative (IT)', 'VIES (EU)');
    const itId = entities.find((e) => e.jurisdiction === 'IT' && /^\d{11}$/.test(String(e.identifier ?? '')));
    if (itId?.identifier) {
      const v = await vies('IT', String(itId.identifier));
      if (v) filings.push(v);
    }
    filings.push(...italyPointers(name));
    warnings.push('The Italian innovative-startup section is published behind a browser check, so its entries are shown as official links to confirm, not as fetched records.');
  }

  filings.sort((a, b) => {
    if (a.verified !== b.verified) return a.verified ? -1 : 1;
    return String(b.date ?? '').localeCompare(String(a.date ?? ''));
  });

  if (filings.filter((f) => f.verified).length === 0) {
    warnings.push('No official filing matched this name. Try the full legal name, including the company suffix.');
  }

  return {
    company: name,
    country: cc || null,
    filings: filings.slice(0, 60),
    entities: entities.slice(0, 8),
    sourcesQueried,
    warnings: [...new Set(warnings)],
    asOf,
  };
}
